#!/usr/bin/env dotnet
#:package Microsoft.CodeAnalysis.CSharp@4.14.0
#:property PublishAot=false

// Find-Methods.cs
//
// Parse-only Roslyn pass (no compilation, no metadata) that lists every method, constructor and
// local function under a source root, with its body, as a JSON catalog for semantic duplicate
// detection. Generated files (the standard auto-generated header marker) and bin/obj are skipped.
//
// Adapted from dotnet/skills find-untested-sources/scripts/Find-UntestedSources.cs (MIT,
// https://github.com/dotnet/skills): the file walk, skip rules, snapshot read, syntax read,
// namespace lookup and diagnostics are kept as written there; the type index became a method list.
//
// Usage:
//   dotnet Find-Methods.cs -- <source-root> <catalog.json> [--preview-lines N]
//
// Output: a JSON array of
//   { id, file, namespace, type, name, signature, startLine, endLine, lineCount, preview, body }
// `id` is the entry's position in the catalog; later steps join their outputs on it.
// `preview` is the first N lines of the body (default 12), for the categorize step.
// Exit codes: 0 ok, 1 bad arguments, 3 finished with diagnostics (listed on stderr).

using System.Collections.Concurrent;
using System.Security.Cryptography;
using System.Text;
using System.Text.Json;
using System.Text.Json.Serialization;
using Microsoft.CodeAnalysis;
using Microsoft.CodeAnalysis.CSharp;
using Microsoft.CodeAnalysis.CSharp.Syntax;

if (!TryParseArguments(args, out var root, out var output, out var previewLines))
{
    Console.Error.WriteLine("usage: dotnet Find-Methods.cs -- <source-root> <catalog.json> [--preview-lines N]");
    return 1;
}

var catalog = EnumerateSourceFiles(root, "*.cs")
    .Order(StringComparer.Ordinal)
    .SelectMany(path => MethodsIn(root, path, previewLines))
    .Select((entry, index) => entry with { Id = index })
    .ToList();

File.WriteAllText(output, JsonSerializer.Serialize(catalog, CatalogJson.Default.ListMethodEntry));
Log($"{catalog.Count} methods from {catalog.Select(m => m.File).Distinct().Count()} files -> {output}");
foreach (var diagnostic in AnalysisState.Diagnostics)
{
    Log($"{diagnostic.code} {diagnostic.path}: {diagnostic.message}");
}
return AnalysisState.Diagnostics.IsEmpty ? 0 : 3;

// ============================================================================
// Method catalog
// ============================================================================

static bool TryParseArguments(string[] args, out string root, out string output, out int previewLines)
{
    root = output = "";
    previewLines = 12;
    if (args.Length is not (2 or 4) || !Directory.Exists(args[0]))
    {
        return false;
    }
    root = Path.GetFullPath(args[0]);
    output = Path.GetFullPath(args[1]);
    return args.Length == 2
        || (args[2] == "--preview-lines" && int.TryParse(args[3], out previewLines) && previewLines > 0);
}

static IEnumerable<MethodEntry> MethodsIn(string root, string path, int previewLines)
{
    var syntax = ReadSyntax(path);
    if (syntax is null || IsAutoGenerated(syntax))
    {
        yield break;
    }
    foreach (var node in syntax.DescendantNodes())
    {
        var (name, parameters) = node switch
        {
            MethodDeclarationSyntax method => (method.Identifier.Text, method.ParameterList),
            ConstructorDeclarationSyntax constructor => (constructor.Identifier.Text + ".ctor", constructor.ParameterList),
            LocalFunctionStatementSyntax local => (local.Identifier.Text, local.ParameterList),
            _ => ((string?)null, (ParameterListSyntax?)null),
        };
        if (name is null)
        {
            continue;
        }
        yield return ToEntry(root, path, node, name, parameters!, previewLines);
    }
}

static MethodEntry ToEntry(string root, string path, SyntaxNode node, string name, ParameterListSyntax parameters, int previewLines)
{
    var span = node.GetLocation().GetLineSpan();
    var body = node.ToString();
    var type = node.Ancestors().OfType<BaseTypeDeclarationSyntax>().FirstOrDefault()?.Identifier.Text ?? "";
    var startLine = span.StartLinePosition.Line + 1;
    var endLine = span.EndLinePosition.Line + 1;
    var preview = string.Join('\n', body.Split('\n').Take(previewLines));
    return new MethodEntry(0, ToRel(root, path), GetNamespaceFor(node), type, name, name + parameters,
        startLine, endLine, endLine - startLine + 1, preview, body);
}

// Generated code carries the standard auto-generated marker in its leading comment.
static bool IsAutoGenerated(SyntaxNode syntax) =>
    syntax.GetLeadingTrivia().Any(trivia => trivia.ToString().Contains("<auto-generated", StringComparison.OrdinalIgnoreCase));

// ============================================================================
// Helpers kept from Find-UntestedSources.cs
// ============================================================================

static IEnumerable<string> EnumerateSourceFiles(string root, string pattern)
{
    var stack = new Stack<string>();
    stack.Push(root);
    while (stack.Count > 0)
    {
        var dir = stack.Pop();
        IEnumerable<string> subdirs;
        try { subdirs = Directory.GetDirectories(dir); }
        catch (Exception ex) when (ex is IOException or UnauthorizedAccessException)
        {
            Report("WALK_FAILED", dir, ex.Message);
            continue;
        }
        foreach (var sub in subdirs)
        {
            if (IsLink(sub)) { continue; }
            var name = Path.GetFileName(sub);
            if (name.Length == 0)
            {
                continue;
            }
            if (string.Equals(name, "bin", StringComparison.OrdinalIgnoreCase)
                || string.Equals(name, "obj", StringComparison.OrdinalIgnoreCase)
                || string.Equals(name, "node_modules", StringComparison.OrdinalIgnoreCase)
                || string.Equals(name, ".git", StringComparison.OrdinalIgnoreCase)
                || string.Equals(name, ".vs", StringComparison.OrdinalIgnoreCase)
                || string.Equals(name, "packages", StringComparison.OrdinalIgnoreCase)
                || name.StartsWith(".", StringComparison.Ordinal))
            {
                continue;
            }
            stack.Push(sub);
        }
        IEnumerable<string> files;
        try { files = Directory.GetFiles(dir, pattern); }
        catch (Exception ex) when (ex is IOException or UnauthorizedAccessException)
        {
            Report("WALK_FAILED", dir, ex.Message);
            continue;
        }
        foreach (var f in files)
        {
            if (IsSkippedFile(f) || IsLink(f))
            {
                continue;
            }
            yield return f;
        }
    }
}

static bool IsSkippedFile(string path)
{
    string[] skippedSuffixes =
    {
        ".g.cs",
        ".Designer.cs",
        ".AssemblyInfo.cs",
        ".AssemblyAttributes.cs",
        ".GlobalUsings.g.cs",
    };
    foreach (var suffix in skippedSuffixes)
    {
        if (path.EndsWith(suffix, StringComparison.OrdinalIgnoreCase))
        {
            return true;
        }
    }
    return false;
}

static string GetNamespaceFor(SyntaxNode node)
{
    // Walk all enclosing namespace declarations and join from outermost to
    // innermost so nested blocks (namespace A { namespace B { ... } }) yield
    // "A.B" rather than just "B".
    List<string>? parts = null;
    foreach (var ns in node.Ancestors().OfType<BaseNamespaceDeclarationSyntax>())
    {
        (parts ??= new List<string>()).Add(ns.Name.ToString());
    }
    if (parts is null)
    {
        return "";
    }
    parts.Reverse();
    return string.Join(".", parts);
}

static string ToRel(string root, string path)
{
    return Path.GetRelativePath(root, path).Replace('\\', '/');
}

static void Log(string msg) => Console.Error.WriteLine($"[find-methods] {msg}");

static void Report(string code, string path, string message)
{
    AnalysisState.Diagnostics.Enqueue(new DiagnosticRecord(code, "warning", path, message));
    AnalysisState.FailedFiles[path] = 0;
}

static bool IsLink(string path)
{
    try { return (File.GetAttributes(path) & FileAttributes.ReparsePoint) != 0; }
    catch (Exception ex) when (ex is IOException or UnauthorizedAccessException)
    {
        Report("STAT_FAILED", path, ex.Message);
        return true;
    }
}

static string ReadSnapshot(string path)
{
    byte[] bytes = File.ReadAllBytes(path);
    string hash = Convert.ToHexString(SHA256.HashData(bytes)).ToLowerInvariant();
    if (AnalysisState.Inputs.TryGetValue(path, out string? previous) && previous != hash)
    {
        Report("INPUT_CHANGED", path, "Input changed during analysis.");
    }
    AnalysisState.Inputs[path] = hash;
    using var stream = new MemoryStream(bytes, writable: false);
    using var reader = new StreamReader(stream, new UTF8Encoding(false, true), detectEncodingFromByteOrderMarks: true);
    return reader.ReadToEnd();
}

static SyntaxNode? ReadSyntax(string path)
{
    try
    {
        var tree = CSharpSyntaxTree.ParseText(ReadSnapshot(path));
        var errors = tree.GetDiagnostics().Where(d => d.Severity == DiagnosticSeverity.Error).Take(3).ToArray();
        if (errors.Length > 0)
        {
            Report("SYNTAX_ERROR", path, string.Join("; ", errors.Select(d => d.ToString())));
            return null;
        }
        return tree.GetRoot();
    }
    catch (Exception ex) when (ex is IOException or UnauthorizedAccessException or DecoderFallbackException)
    {
        Report("READ_FAILED", path, ex.Message);
        return null;
    }
}

internal sealed record MethodEntry(
    int Id, string File, string Namespace, string Type, string Name, string Signature,
    int StartLine, int EndLine, int LineCount, string Preview, string Body);

internal sealed record DiagnosticRecord(string code, string severity, string path, string message);

internal static class AnalysisState
{
    internal static readonly ConcurrentQueue<DiagnosticRecord> Diagnostics = new();
    internal static readonly ConcurrentDictionary<string, string> Inputs = new(StringComparer.Ordinal);
    internal static readonly ConcurrentDictionary<string, byte> FailedFiles = new(StringComparer.Ordinal);
}

[JsonSourceGenerationOptions(WriteIndented = true, PropertyNamingPolicy = JsonKnownNamingPolicy.CamelCase)]
[JsonSerializable(typeof(List<MethodEntry>))]
internal sealed partial class CatalogJson : JsonSerializerContext;
